<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='GET'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $q='%'.trim((string)($_GET['q']??'')).'%'; $s=$db->prepare("SELECT DISTINCT u.id,u.full_name,u.username,u.profile_photo FROM users u WHERE u.status='active' AND u.id<>:uid AND (u.full_name LIKE :q OR u.username LIKE :q) AND (EXISTS(SELECT 1 FROM friendships f WHERE ((f.user_id=:uid AND f.friend_id=u.id) OR (f.user_id=u.id AND f.friend_id=:uid)) AND f.status='accepted') OR EXISTS(SELECT 1 FROM family_members fm WHERE fm.user_id=:uid AND fm.family_member_id=u.id AND fm.status='active' AND fm.approved=1)) AND NOT EXISTS(SELECT 1 FROM friendships b WHERE ((b.user_id=:uid AND b.friend_id=u.id) OR (b.user_id=u.id AND b.friend_id=:uid)) AND b.status='blocked') ORDER BY u.full_name ASC LIMIT 30"); $s->execute(['uid'=>$uid,'q'=>$q]); ApiResponse::success(['users'=>$s->fetchAll(PDO::FETCH_ASSOC)],'Invitees loaded.'); }catch(Throwable $e){Logger::error('Journey invitee list failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to load invitees.');}
?>
